
"""
File: models.py

Purpose:
Define SQLAlchemy ORM models for persistent ScamShield KE data.

AnalysisRecord stores the submitted message and the explainable
screening results returned by the analysis service.
"""

from datetime import datetime

from sqlalchemy import JSON, DateTime, Float, Integer, String, Text, func
from sqlalchemy.orm import Mapped, mapped_column

from scamshield.db.database import Base


class AnalysisRecord(Base):
    """Represent one saved message-screening analysis."""

    __tablename__ = "analysis_records"

    # Unique identifier generated by the database.
    id: Mapped[int] = mapped_column(
        Integer,
        primary_key=True,
        index=True,
    )

    # Original message submitted for screening.
    message: Mapped[str] = mapped_column(
        Text,
        nullable=False,
    )

    # Machine-learning prediction and estimated class scores.
    predicted_label: Mapped[str] = mapped_column(
        String(10),
        nullable=False,
        index=True,
    )

    ham_probability: Mapped[float] = mapped_column(
        Float,
        nullable=False,
    )

    spam_probability: Mapped[float] = mapped_column(
        Float,
        nullable=False,
    )

    # Combined assessment from the ML model and rule engine.
    risk_level: Mapped[str] = mapped_column(
        String(10),
        nullable=False,
        index=True,
    )

    # PostgreSQL JSON stores structured findings and text lists.
    risk_reasons: Mapped[list] = mapped_column(
        JSON,
        nullable=False,
        default=list,
    )

    findings: Mapped[list] = mapped_column(
        JSON,
        nullable=False,
        default=list,
    )

    recommendations: Mapped[list] = mapped_column(
        JSON,
        nullable=False,
        default=list,
    )

    # The database supplies the creation timestamp.
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        index=True,
    )
